// ---------- i18n ----------
// The UI language is saved per browser (defaults to the browser language). Switching reloads the page
// Values are inserted as raw HTML, so callers must escape user data before passing it in params
const LANGS = { ja: '日本語', ko: '한국어', en: 'English' };
const browserLang = () => {
  const nav = (navigator.language || '').slice(0, 2);
  return LANGS[nav] ? nav : 'en';
};
const lang = (() => {
  try { const saved = localStorage.getItem('docket-lang'); if (LANGS[saved]) return saved; } catch {}
  return browserLang();
})();
document.documentElement.lang = lang;

